import React, {
  useEffect,
  useState
} from "react";

function Packets() {
  const [packets,
    setPackets] =
    useState([]);

  useEffect(() => {
    const token =
      localStorage.getItem(
        "access_token"
      );

    fetch(
      "http://127.0.0.1:8000/packets/",
      {
        headers: {
          Authorization:
            `Bearer ${token}`
        }
      }
    )
      .then((res) => res.json())
      .then((data) => {
        setPackets(
          data.packets || []
        );
      })
      .catch((err) =>
        console.error(err)
      );
  }, []);

  return (
    <div style={styles.main}>
      <h1>Packets</h1>

      {packets.map(
        (packet) => (
          <div
            key={packet.id}
            style={styles.card}
          >
            <p>
              Source:
              {" "}
              {packet.source_ip}
            </p>

            <p>
              Destination:
              {" "}
              {packet.destination_ip}
            </p>
          </div>
        )
      )}
    </div>
  );
}

const styles = {
  main: {
    flex: 1,
    padding: "30px"
  },
  card: {
    background: "#1e293b",
    padding: "20px",
    borderRadius: "10px",
    marginBottom: "15px"
  }
};

export default Packets;
